questions.uml_mutation:
class Cart {
    -String cartId
    -double totalAmount
}
Cart o-- Coupon : applies_to

class CartItem {
    -String productId
    -double price
    -int quantity
}
Cart "1" *-- "*" CartItem : contains

class DiscountPolicy {
    +calculateDiscount(Cart cart) : double
}
class PercentagePolicy {
    -double percentage
    +calculateDiscount(Cart cart) : double
}
class FlatAmountPolicy {
    -double amount
    +calculateDiscount(Cart cart) : double
}

class CouponValidator {
    <<interface>>
    +validate(Coupon coupon, Cart cart) : boolean
}
class ExpiryValidator {
    +validate(Coupon coupon, Cart cart) : boolean
}
class MinAmountValidator {
    +validate(Coupon coupon, Cart cart) : boolean
}
CouponValidator <|.. ExpiryValidator
CouponValidator <|.. MinAmountValidator

class CouponValidator {
    +setNext(CouponValidator nextValidator)
}
ExpiryValidator o-- CouponValidator : next
MinAmountValidator o-- CouponValidator : next

class CouponService {
    -CouponValidator validatorChain
    +applyCoupon(String code, Cart cart) : double
}
CouponService --> CouponValidator : triggers_validation
CouponService --> Coupon : retrieves

class CouponService {
    -CouponValidator validatorChain
    +applyCoupon(String code, Cart cart) : double
    +redeemCoupon(String code, String userId) : boolean
}

class CouponUsage {
    -String usageId
    -String userId
    -LocalDateTime usedAt
}
Coupon "1" *-- "*" CouponUsage : tracks_history
